package com.ruoyi.medical.persistence;
import java.util.*;
import com.ruoyi.medical.persistence.mapper.*;
import org.junit.jupiter.api.*;
import org.springframework.jdbc.core.RowMapper;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.mockito.ArgumentMatchers.*;
/** Real complete-graph/current grant algorithm with actual private-proof types mocked. */
class RuntimeGovernanceCurrentAuthorityTest {
 FormalWorkerAccessTest f;RuntimeGovernanceCurrentAuthority authority;RuntimeReplaySchema.VerifiedInputs input;AgentExecutionPolicyRegisteredAuthority.RegisteredPolicyIdentity policy;RuntimeRetentionAuthority.Verified retention;ArtifactRegistryMapper registry;VersionResourceMapper owners;SourceReadMapper lineage;ResourceReadAuthority resources;com.fasterxml.jackson.databind.node.ObjectNode value;
 String pv,rv,tv;PermissionProtocol.Scope policyScope;List<AgentExecutionPolicyProtocol.ActionBinding> bindings;
 @BeforeEach void setup()throws Exception{
  f=new FormalWorkerAccessTest();f.setUp();pv=f.id(80);rv=f.id(81);tv=f.id(82);input=mock(RuntimeReplaySchema.VerifiedInputs.class);policy=mock(AgentExecutionPolicyRegisteredAuthority.RegisteredPolicyIdentity.class);retention=mock(RuntimeRetentionAuthority.Verified.class);registry=mock(ArtifactRegistryMapper.class);owners=mock(VersionResourceMapper.class);lineage=mock(SourceReadMapper.class);resources=mock(ResourceReadAuthority.class);
  policyScope=new PermissionProtocol.Scope(f.tenant,null,"CONFIGURATION",f.id(83));when(policy.ownerScope()).thenReturn(policyScope);when(policy.versionId()).thenReturn(pv);when(policy.contentSha256()).thenReturn("a".repeat(64));when(policy.ownsVersion(pv,"a".repeat(64))).thenReturn(true);when(policy.worker()).thenReturn(new AgentExecutionPolicyProtocol.Worker("spiffe://medical/runtime","medical-runtime"));when(retention.policyRevision()).thenReturn(rv);when(retention.contentSha256()).thenReturn("a".repeat(64));when(retention.ownerScope()).thenReturn(new PermissionProtocol.Scope(f.tenant,f.project,"PROJECT",f.project));
  value=f.schema.object().put("task_id",f.task).put("project_id",f.project);value.putObject("execution_policy_version").put("version_id",pv).put("content_sha256","a".repeat(64));value.putObject("retention").put("policy_revision",rv).put("content_sha256","a".repeat(64));value.putObject("scope_snapshot").putArray("members");value.putArray("dependency_edges");var deps=value.putArray("dependency_versions");
  for(var pair:List.of(Map.entry(pv,"AGENT_EXECUTION_POLICY"),Map.entry(rv,"RUNTIME_RETENTION_POLICY"),Map.entry(tv,"TASK_REVISION"))){String project=pair.getKey().equals(pv)?null:f.project;deps.addObject().put("version_id",pair.getKey()).put("project_id",project).put("entity_kind",pair.getValue()).put("content_sha256","a".repeat(64));when(registry.version(pair.getKey())).thenReturn(List.of(new ArtifactRegistryProtocol.VersionRow(pair.getKey(),project,pair.getValue(),"a".repeat(64))));when(lineage.parents(pair.getKey())).thenReturn(List.of());}
  when(owners.ownersAcrossDomains(anyList(),anyList())).thenAnswer(x->ownerRows());
  bindings=List.of(new AgentExecutionPolicyProtocol.ActionBinding("CONFIGURATION","CURRENT_EXECUTION_POLICY","configuration.read","TASK_EXECUTION",null,List.of()),new AgentExecutionPolicyProtocol.ActionBinding("PROJECT","PROJECT","retention.read","RUN_CREATION",null,List.of()),new AgentExecutionPolicyProtocol.ActionBinding("TASK","TASK","task.read","TASK_EXECUTION",null,List.of()));node();
  when(f.jdbc.query(contains("SELECT n.node_kind"),any(RowMapper.class),eq(f.tenant),eq(f.project),eq(f.run),eq(f.step),eq(pv),eq("a".repeat(64)),eq(f.actor))).thenReturn(List.of(new RuntimeGovernanceCurrentAuthority.Node("N00",f.id(84),"b".repeat(64))));
  when(input.runId()).thenReturn(f.run);when(input.content()).thenAnswer(x->value.deepCopy());authority=new RuntimeGovernanceCurrentAuthority(f.jdbc,owners,registry,lineage,resources,new PermissionSchema());
 }
 List<VersionResourceProtocol.DomainOwnerRow> ownerRows(){return List.of(new VersionResourceProtocol.DomainOwnerRow("AGENT_EXECUTION_POLICY",new VersionResourceProtocol.OwnerRow(f.tenant,pv,null,null,"CONFIGURATION",policyScope.resource_id(),"a".repeat(64),null,null,null,null)),new VersionResourceProtocol.DomainOwnerRow("TASK_REVISION",new VersionResourceProtocol.OwnerRow(f.tenant,tv,f.project,f.project,"TASK",f.task,"a".repeat(64),null,null,null,null)));}
 @Test void actualRegisteredPolicyOwnerIsRequired(){when(owners.ownersAcrossDomains(anyList(),anyList())).thenReturn(ownerRows().subList(1,2));assertThrows(TenantAccessException.class,this::run);}
 @Test void actualPolicyOwnerCannotBorrowOtherConfiguration(){var rows=new ArrayList<>(ownerRows());rows.set(0,new VersionResourceProtocol.DomainOwnerRow("AGENT_EXECUTION_POLICY",new VersionResourceProtocol.OwnerRow(f.tenant,pv,null,null,"CONFIGURATION",f.id(99),"a".repeat(64),null,null,null,null)));when(owners.ownersAcrossDomains(anyList(),anyList())).thenReturn(rows);assertThrows(TenantAccessException.class,this::run);}
 @Test void exactOwnedPolicyComponentSharesOnlyExplicitCurrentPolicySelector()throws Exception{String component=f.id(85),hash="c".repeat(64);value.withArray("dependency_versions").addObject().put("version_id",component).putNull("project_id").put("entity_kind","AGENT_NETWORK_POLICY").put("content_sha256",hash);when(registry.version(component)).thenReturn(List.of(new ArtifactRegistryProtocol.VersionRow(component,null,"AGENT_NETWORK_POLICY",hash)));when(lineage.parents(component)).thenReturn(List.of());var rows=new ArrayList<>(ownerRows());rows.add(new VersionResourceProtocol.DomainOwnerRow("AGENT_NETWORK_POLICY",new VersionResourceProtocol.OwnerRow(f.tenant,component,null,null,"CONFIGURATION",policyScope.resource_id(),hash,null,null,null,null)));when(owners.ownersAcrossDomains(anyList(),anyList())).thenReturn(rows);when(policy.ownsVersion(component,hash)).thenReturn(true);run();verify(resources,times(2)).require(any(),eq(policyScope),eq("configuration.read"),eq("TASK_EXECUTION"));when(policy.ownsVersion(component,hash)).thenReturn(false);assertThrows(TenantAccessException.class,this::run);}
 void node(){when(policy.requireNode(anyString(),any(),anyString(),anyString())).thenReturn(new AgentExecutionPolicyProtocol.NodeBinding("N00",new PermissionProtocol.Basis(f.id(84),"b".repeat(64)),null,null,null,f.schema.object(),bindings));}
 void run()throws Exception{f.access.execute(f.http,"actual-token-fixture",f.request,a->{try{return authority.require(a,input,policy,retention);}catch(RuntimeException e){throw e;}catch(Exception e){throw new RuntimeException(e);}});}
 @AfterEach void cleanup(){f.cleanup();}
 @Test void enterprisePolicyUsesActualNullOwnerAndExplicitPurpose()throws Exception{run();verify(resources).require(any(),eq(policyScope),eq("configuration.read"),eq("TASK_EXECUTION"));verify(resources).require(any(),eq(new PermissionProtocol.Scope(f.tenant,f.project,"PROJECT",f.project)),eq("retention.read"),eq("RUN_CREATION"));}
 @Test void revokedCurrentGovernanceGrantRejected()throws Exception{doThrow(new TenantAccessException(com.ruoyi.medical.contracts.ErrorCode.ACCESS_DENIED)).when(resources).require(any(),eq(policyScope),anyString(),anyString());assertThrows(TenantAccessException.class,this::run);}
 @Test void enterpriseRetentionCannotBorrowProjectSelector(){when(retention.ownerScope()).thenReturn(new PermissionProtocol.Scope(f.tenant,null,"ENTERPRISE",f.tenant));assertThrows(TenantAccessException.class,this::run);}
 @Test void newActualEdgeMissingFromOriginalRejected(){when(lineage.parents(tv)).thenReturn(List.of(new SourceReadProtocol.ParentRow(tv,pv,"CHANGED")));assertThrows(TenantAccessException.class,this::run);}
 @Test void changedRegistryHashRejected(){when(registry.version(tv)).thenReturn(List.of(new ArtifactRegistryProtocol.VersionRow(tv,f.project,"TASK_REVISION","f".repeat(64))));assertThrows(TenantAccessException.class,this::run);}
 @Test void missingApprovedReadIsNotAutomaticallyAdded(){bindings=bindings.subList(0,2);node();assertThrows(TenantAccessException.class,this::run);}
}
